import type { GenericEndpointContext } from "@better-auth/core";
import { APIError } from "better-auth/api";
import {
	generateRandomString,
	symmetricDecrypt,
	symmetricEncrypt,
} from "better-auth/crypto";
import type {
	DpopReplayReservation,
	DpopReplayStore,
} from "better-auth/oauth2";
import {
