interface CandidateName {
  readonly norm: string;
  readonly words: readonly string[];
  readonly wordCount: number;
}

const extractCandidateNames = (roster: Roster): readonly CandidateName[] => {
  const rawNames = new Set<string>();

  for (const item of roster) {
    if (typeof item === "string") {
      const trimmed = item.trim();

      if (trimmed.includes("@")) {
        const localPart = trimmed.split("@")[0] ?? "";

        if (localPart) {
          rawNames.add(localPart);

          for (const sub of localPart.split(/[._-]/)) {
            if (sub) {
              rawNames.add(sub);
            }
          }
        }
      } else {
        rawNames.add(trimmed);

        for (const sub of trimmed.split(/\s+/)) {
          if (sub) {
            rawNames.add(sub);
          }
        }
      }
    } else if (item && typeof item === "object") {
      if (item.name) {
        rawNames.add(item.name.trim());

        for (const sub of item.name.trim().split(/\s+/)) {
          if (sub) {
            rawNames.add(sub);
          }
        }
      }

      if (item.firstName) {
        rawNames.add(item.firstName.trim());
      }

      if (item.lastName) {
        rawNames.add(item.lastName.trim());
      }

      if (item.email) {
        const localPart = item.email.trim().split("@")[0] ?? "";

        if (localPart) {
          rawNames.add(localPart);

          for (const sub of localPart.split(/[._-]/)) {
            if (sub) {
              rawNames.add(sub);
            }
          }
        }
      }
    }
  }

  const seen = new Set<string>();
  const candidates: CandidateName[] = [];

  for (const name of rawNames) {
    const norm = stripDiacritics(name.trim());

    if (norm.length < 2 || seen.has(norm)) {
      continue;
    }

    seen.add(norm);

    const words = norm.split(/\s+/).filter((w) => w.length > 0);

    if (words.length > 0) {
      candidates.push({
        norm,
        words,
        wordCount: words.length,
      });
    }
  }

  return candidates.sort((a, b) => b.wordCount - a.wordCount || b.norm.length - a.norm.length);
};

const redactNames = (text: string, candidates: readonly CandidateName[]): string => {
  if (candidates.length === 0) {
    return text;
  }

  const segmenter = new Intl.Segmenter("en", { granularity: "word" });
  const segments = [...segmenter.segment(text)];

  let result = "";
  let i = 0;

  while (i < segments.length) {
    const seg = segments[i];

    if (seg === undefined) {
      break;
    }

    if (!seg.isWordLike) {
      result += seg.segment;
      i++;
      continue;
    }

    let matched = false;

    for (const candidate of candidates) {
      if (candidate.wordCount > 1) {
        let wordIdx = i;
        let matchedCount = 0;
        let spanEnd = i;
        const collectedWords: string[] = [];
        let possessiveSuffix = "";

        while (wordIdx < segments.length && matchedCount < candidate.wordCount) {
          const nextSeg = segments[wordIdx];

          if (nextSeg === undefined) {
            break;
          }

          if (nextSeg.isWordLike) {
            let segWord = nextSeg.segment;

            if (
              matchedCount === candidate.wordCount - 1 &&
              (segWord.endsWith("'s") || segWord.endsWith("’s"))
            ) {
              possessiveSuffix = segWord.slice(-2);
              segWord = segWord.slice(0, -2);
            }

            collectedWords.push(stripDiacritics(segWord));
            matchedCount++;
            spanEnd = wordIdx;
          }

          wordIdx++;
        }

        if (matchedCount === candidate.wordCount && collectedWords.join(" ") === candidate.words.join(" ")) {
          result += `[name]${possessiveSuffix}`;
          i = spanEnd + 1;
          matched = true;
          break;
        }
      } else {
        let word = seg.segment;
        let suffix = "";

        if (word.endsWith("'s") || word.endsWith("’s")) {
          suffix = word.slice(-2);
          word = word.slice(0, -2);
        }

        if (stripDiacritics(word) === candidate.norm) {
          result += `[name]${suffix}`;
          i++;
          matched = true;
          break;
        }
      }
    }

    if (!matched) {
      result += seg.segment;
      i++;
    }
  }

  return result;
};

export const redact = (text: string, roster: Roster): string => {
  if (!text) {
    return "";
  }

  const normalized = text.normalize("NFC");

  const bounded =
    normalized.length > Policy.text.longTextMaxLength
      ? normalized.slice(0, Policy.text.longTextMaxLength)
      : normalized;

  let result = bounded.replaceAll(URL_PATTERN, "[link]");

  result = result.replaceAll(EMAIL_PATTERN, "[email]");

  result = result.replaceAll(HANDLE_PATTERN, "[handle]");

  result = redactGermanPhones(result);

  result = redactGenericPhones(result);

  const candidates = extractCandidateNames(roster);
  result = redactNames(result, candidates);

  return result;
};

