    "amazon-bedrock/eu-west-1",
    "sb_edit_",
    "sb_answers_",
    "Clear my answers on this device",
    "edpb.europa.eu",
  ])("discloses %s", (needle) => {
    expect(text).toContain(needle);
  });

  it("states the retention periods from the code and the policy", () => {
    expect(text).toContain("24 months");
